const { writeFileSync, promises: fsPromises } = await import('node:fs');
if (!globalThis.input || typeof globalThis.input.html !== 'string') {
  throw new Error('Missing required input: html');
}
const htmlPath = '/tmp/input.html';
writeFileSync(htmlPath, globalThis.input.html, 'utf8');
globalThis.htmlPath = htmlPath;

const { chromium } = await import('playwright');
const browser = await chromium.launch();
const page = await browser.newPage();
const { readFile } = await import('node:fs').then(m => m.promises);
const htmlContent = await readFile(globalThis.htmlPath, 'utf8');
await page.setContent(htmlContent);
const scriptPath = process.cwd() + '/node_modules/html3pdf/dist/html3pdf.js';
await page.addScriptTag({ path: scriptPath });
// Wait for the global html2pdf function to be available
await page.waitForFunction(() => typeof html2pdf === 'function');
const dataUri = await page.evaluate(async () => {
  // html2pdf returns a Worker; we ask it to output a PDF as a data‑uri string
  const result = await html2pdf().outputPdf('datauristring');
  return result;
});
globalThis.pdfDataUri = dataUri;
await browser.close();

const dataUri = globalThis.pdfDataUri;
if (typeof dataUri !== 'string' || !dataUri.includes(',')) {
  throw new Error('Invalid PDF data URI');
}
const base64 = dataUri.split(',')[1];
console.log(JSON.stringify({ pdf_base64: base64 }));
